package vaultor.linked;
import java.nio.file.*;import java.util.*;

public final class LinkedDirectoryTests extends SafetyTests {
    public static void main(String[] args)throws Exception {
        check("native hierarchy lists directories first with exact Unicode file identity",()->{try(var f=new LinkedPublicationTests.LinkedFixture("文档 😀.md","# Source",null)){Files.createDirectory(f.root.resolve("architecture"));Files.writeString(f.root.resolve("asset.png"),"fixture");var entries=f.store.listDirectory(OWNER,f.rootCap,"",0,100);require(entries.getFirst().directory());require(entries.getFirst().name().equals("architecture"));var source=entries.stream().filter(e->e.name().equals("文档 😀.md")).findFirst().orElseThrow();require(source.markdown());require(source.identity().equals(f.doc.base().revision().identity()));require(!source.unsupported());}});
        check("directory pages are bounded and stable",()->{try(var f=new LinkedPublicationTests.LinkedFixture("guide.md","Base",null)){for(int i=0;i<150;i++)Files.writeString(f.root.resolve(String.format(Locale.ROOT,"doc-%03d.md",i)),"# Page");var first=f.store.listDirectory(OWNER,f.rootCap,"",0,75);var next=f.store.listDirectory(OWNER,f.rootCap,"",75,75);require(first.size()==75&&next.size()==75);require(Collections.disjoint(first.stream().map(LinkedStore.Entry::name).toList(),next.stream().map(LinkedStore.Entry::name).toList()));}});
        check("native traversal, private recovery and Git internals are not browsable",()->{try(var f=new LinkedPublicationTests.LinkedFixture("guide.md","Base",null)){Files.createDirectory(f.root.resolve(".git"));Files.createDirectory(f.root.resolve(".vaultor-recovery-test"));require(f.store.listDirectory(OWNER,f.rootCap,"",0,100).size()==1);rejects("RELATIVE",()->f.store.listDirectory(OWNER,f.rootCap,"../outside",0,10));rejects("RELATIVE",()->f.store.listDirectory(OWNER,f.rootCap,".git",0,10));}});
        check("junction entries are visible as unsupported and never traversed",()->{try(var f=new LinkedPublicationTests.LinkedFixture("guide.md","Base",null)){Path outside=Files.createDirectory(f.dir.resolve("outside")),link=Files.createDirectory(f.root.resolve("alias"));Files.writeString(outside.resolve("secret.md"),"Outside");require(external("junction",link,outside.toString())==0);var entry=f.store.listDirectory(OWNER,f.rootCap,"",0,100).stream().filter(e->e.name().equals("alias")).findFirst().orElseThrow();require(entry.unsupported());rejects("REPARSE",()->f.store.listDirectory(OWNER,f.rootCap,"alias",0,10));require(Files.readString(outside.resolve("secret.md")).equals("Outside"));}});
        check("revoked and non-owner directory requests refuse",()->{try(var f=new LinkedPublicationTests.LinkedFixture("guide.md","Base",null)){rejects("SCOPE",()->f.store.listDirectory(new LinkedStore.Scope("workspace","generation",LinkedStore.Client.BROWSER),f.rootCap,"",0,10));f.store.revoke(OWNER,f.rootCap);rejects("ROOT",()->f.store.listDirectory(OWNER,f.rootCap,"",0,10));}});
        Files.writeString(Path.of("native/linked-markdown/evidence/production/directory-tests.txt"),String.join("\n",results)+"\npassed="+passed+" failed="+failed+"\n");System.out.println("TOTAL "+passed+" passed; "+failed+" failed");if(failed>0)System.exit(1);
    }
}
